    const appPath = require('path').join(ROOT, 'js', 'app.js');
    const appSource = require('fs').readFileSync(appPath, 'utf8');

    // Clear and re-write the document body.
    // document.write() on a closed document opens a new stream and replaces the page.
    w.document.open();
    w.document.write(require('fs').readFileSync(indexPath, 'utf8'));
    w.document.close();

    // Restore localStorage.
    for (var key in savedStorage) {
      if (savedStorage.hasOwnProperty(key)) {
        w.localStorage.setItem(key, savedStorage[key]);
      }
    }

    // Re-evaluate the app and dispatch lifecycle events.
    w.eval(appSource);
    w.document.dispatchEvent(new w.Event('DOMContentLoaded', { bubbles: true }));
    w.dispatchEvent(new w.Event('load'));

    this.document = w.document;
    return this.document;
