 * @planks("I navigate to {string}")
 * @planks("I complete {string}")
 * @planks("I un-complete {string}")
 * @planks("the todos are {string} and {string}")
 * @planks("the todo {string} has class {string}")
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todoApp = document.querySelector('.todoapp');
  var newTodoInput = todoApp.querySelector('.new-todo');
  var todoList = todoApp.querySelector('.todo-list');
  var mainSection = todoApp.querySelector('.main');
  var footer = todoApp.querySelector('.footer');
  var todoCount = todoApp.querySelector('.todo-count');
  var clearCompletedBtn = todoApp.querySelector('.clear-completed');
  var toggleAllCheckbox = todoApp.querySelector('#toggle-all');
  var filterLinks = todoApp.querySelectorAll('.filters a');

  var todos = [];
  var currentFilter = 'all';

  // --- Model ---

  function loadTodos() {
    try {
      todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    todos.push({ id: generateId(), title: trimmed, completed: false });
    saveTodos();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    saveTodos();
    render();
  }

  function toggleAll(completed) {
    todos.forEach(function (t) { t.completed = completed; });
    saveTodos();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function updateTodo(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      removeTodo(id);
      return;
    }
    todos.forEach(function (t) {
      if (t.id === id) t.title = trimmed;
    });
    saveTodos();
    render();
  }

  function getFilteredTodos() {
    if (currentFilter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (currentFilter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  // --- Render ---

  function render() {
    var filtered = getFilteredTodos();
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    // Show/hide main and footer
    var hasTodos = todos.length > 0;
    mainSection.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Render list
    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      if (todo.completed) li.className = 'completed';

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      // Toggle checkbox
      li.querySelector('.toggle').addEventListener('change', function () {
        toggleTodo(todo.id);
      });

      // Destroy button
      li.querySelector('.destroy').addEventListener('click', function () {
        removeTodo(todo.id);
      });

      // Double-click label for editing
      li.querySelector('label').addEventListener('dblclick', function () {
        var editInput = li.querySelector('.edit');
        li.classList.add('editing');
        editInput.focus();
        editInput.value = todo.title;
      });

      // Edit input events
      var editInput = li.querySelector('.edit');
      editInput.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          e.preventDefault();
          updateTodo(todo.id, editInput.value);
        }
        if (e.keyCode === ESCAPE_KEY) {
          editInput.value = todo.title;
          li.classList.remove('editing');
        }
      });
      editInput.addEventListener('blur', function () {
        if (li.classList.contains('editing')) {
          updateTodo(todo.id, editInput.value);
        }
      });

      todoList.appendChild(li);
    });

    // Update toggle-all checkbox
    toggleAllCheckbox.checked = completedCount === todos.length && todos.length > 0;

    // Update counter
    var itemWord = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

    // Show/hide clear completed
    clearCompletedBtn.style.display = completedCount > 0 ? 'block' : 'none';

    // Update filter link classes
    Array.prototype.forEach.call(filterLinks, function (link) {
      var href = link.getAttribute('href');
      var filter = 'all';
      if (href === '#/active') filter = 'active';
      else if (href === '#/completed') filter = 'completed';
      if (filter === currentFilter) {
        link.className = 'selected';
      } else {
        link.className = '';
      }
    });
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  // --- Events ---

  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  toggleAllCheckbox.addEventListener('change', function () {
    toggleAll(toggleAllCheckbox.checked);
  });

  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // --- Routing ---

  function handleHashChange() {
    var hash = window.location.hash;
    if (hash === '#/active') currentFilter = 'active';
    else if (hash === '#/completed') currentFilter = 'completed';
    else currentFilter = 'all';
    render();
  }

  window.addEventListener('hashchange', handleHashChange);

  // --- Init ---

  loadTodos();
  handleHashChange();
  newTodoInput.focus();
})();

